class MemoryCorrelatedSubqueryTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void projectedExistsAndNotExistsKeepCorrelatedOuterValuesAfterOptimization() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(VF.createIRI("urn:s1"), VF.createIRI("urn:p"), VF.createLiteral(1));
			connection.add(VF.createIRI("urn:s2"), VF.createIRI("urn:p"), VF.createLiteral(2));
			connection.add(VF.createIRI("urn:z"), VF.createIRI("urn:q"), VF.createLiteral("present"));

			List<BindingSet> existsRows = evaluate(connection, """
					SELECT ?x WHERE {
					  ?s <urn:p> ?x
					  FILTER EXISTS {
					    SELECT ?x WHERE {
					      ?z <urn:q> ?v
					      FILTER(?x = 1)
					    }
					  }
					}
					""");
			assertThat(existsRows).hasSize(1);
			assertThat(existsRows.getFirst().getValue("x")).isEqualTo(VF.createLiteral(1));

			List<BindingSet> notExistsRows = evaluate(connection, """
					SELECT ?x WHERE {
					  ?s <urn:p> ?x
					  FILTER NOT EXISTS {
					    SELECT ?x WHERE {
					      ?z <urn:q> ?v
					      FILTER(?x = 1)
					    }
					  }
					}
					""");
			assertThat(notExistsRows).hasSize(1);
			assertThat(notExistsRows.getFirst().getValue("x")).isEqualTo(VF.createLiteral(2));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void projectedCorrelationMatrixMatchesExpectedBagsAcrossSubqueryOperators() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			Value one = VF.createLiteral("1", XSD.INTEGER);
			Value two = VF.createLiteral("2", XSD.INTEGER);
			List<String> subqueries = List.of(
					"SELECT ?x (?x AS ?copy) WHERE { VALUES ?z { 1 } FILTER(?x = 1) }",
					"SELECT DISTINCT ?x (?x AS ?copy) WHERE { VALUES ?z { 1 1 } FILTER(?x = 1) } "
							+ "ORDER BY ?copy LIMIT 1",
					"SELECT ?x (?x AS ?copy) WHERE { { VALUES ?z { 1 } } UNION { VALUES ?w { 2 } } "
							+ "OPTIONAL { VALUES ?opt { 3 } } MINUS { VALUES ?none { 4 } } FILTER(?x = 1) }");
			List<BindingSet> existsExpected = List.of(row("x", one), row("x", one));
			List<BindingSet> notExistsExpected = List.of(row("x", two), new MapBindingSet());
			List<BindingSet> bindExpected = List.of(
					row("x", one, "ok", VF.createLiteral(true)),
					row("x", one, "ok", VF.createLiteral(true)),
					row("x", two, "ok", VF.createLiteral(false)),
					row("ok", VF.createLiteral(false)));

			for (String subquery : subqueries) {
				String outer = "VALUES ?x { 1 2 UNDEF 1 } ";
				assertThat(evaluate(connection, "SELECT ?x WHERE { " + outer
						+ "FILTER EXISTS { " + subquery + " } }"))
								.as("EXISTS with %s", subquery)
								.containsExactlyInAnyOrderElementsOf(existsExpected);
				assertThat(evaluate(connection, "SELECT ?x WHERE { " + outer
						+ "FILTER NOT EXISTS { " + subquery + " } }"))
								.as("NOT EXISTS with %s", subquery)
								.containsExactlyInAnyOrderElementsOf(notExistsExpected);
				assertThat(evaluate(connection, "SELECT ?x ?ok WHERE { " + outer
						+ "BIND(EXISTS { " + subquery + " } AS ?ok) }"))
								.as("BIND(EXISTS) with %s", subquery)
								.containsExactlyInAnyOrderElementsOf(bindExpected);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void version12UnprojectedSubqueryUsesOptionalOuterBindingForAllPolarities() {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			var marker = VF.createIRI("urn:marker");
			var predicate = VF.createIRI("urn:p");
			var seed1 = VF.createIRI("urn:seed1");
			var seed1Copy = VF.createIRI("urn:seed1-copy");
			var seed2 = VF.createIRI("urn:seed2");
			var missingSeed = VF.createIRI("urn:seed-missing");
			for (var seed : List.of(seed1, seed1Copy, seed2, missingSeed)) {
				connection.add(seed, marker, VF.createLiteral(true));
			}
			connection.add(seed1, predicate, VF.createLiteral("1", XSD.INTEGER));
			connection.add(seed1Copy, predicate, VF.createLiteral("1", XSD.INTEGER));
			connection.add(seed2, predicate, VF.createLiteral("2", XSD.INTEGER));
			connection.add(VF.createIRI("urn:witness"), VF.createIRI("urn:q"), VF.createIRI("urn:object"));

			MapBindingSet x1 = row("x", VF.createLiteral("1", XSD.INTEGER));
			MapBindingSet x2 = row("x", VF.createLiteral("2", XSD.INTEGER));
			MapBindingSet unboundX = new MapBindingSet();
			List<BindingSet> existsExpected = List.of(x1, x1);
			List<BindingSet> notExistsExpected = List.of(x2, unboundX);
			MapBindingSet x1True = row("x", VF.createLiteral("1", XSD.INTEGER), "ok", VF.createLiteral(true));
			MapBindingSet x2False = row("x", VF.createLiteral("2", XSD.INTEGER), "ok", VF.createLiteral(false));
			MapBindingSet unboundFalse = row("ok", VF.createLiteral(false));
			List<BindingSet> bindExpected = List.of(x1True, x1True, x2False, unboundFalse);

			String outer = "?seed <urn:marker> true OPTIONAL { ?seed <urn:p> ?x } ";
			String subquery = "SELECT ?z WHERE { ?z <urn:q> ?v FILTER(?x = 1) }";
			assertThat(evaluate(connection, "VERSION \"1.2\" SELECT ?x WHERE { " + outer
					+ "FILTER EXISTS { " + subquery + " } }"))
							.containsExactlyInAnyOrderElementsOf(existsExpected);
			assertThat(evaluate(connection, "VERSION \"1.2\" SELECT ?x WHERE { " + outer
					+ "FILTER NOT EXISTS { " + subquery + " } }"))
							.containsExactlyInAnyOrderElementsOf(notExistsExpected);
			assertThat(evaluate(connection, "VERSION \"1.2\" SELECT ?x ?ok WHERE { " + outer
					+ "BIND(EXISTS { " + subquery + " } AS ?ok) }"))
							.containsExactlyInAnyOrderElementsOf(bindExpected);
		} finally {
			repository.shutDown();
		}
	}

	private static List<BindingSet> evaluate(RepositoryConnection connection, String query) {
		List<BindingSet> rows = new ArrayList<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	private static MapBindingSet row(String name, Value value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding(name, value);
		return row;
	}

	private static MapBindingSet row(String firstName, Value firstValue, String secondName, Value secondValue) {
		MapBindingSet row = row(firstName, firstValue);
		row.addBinding(secondName, secondValue);
		return row;
	}

}
